typedef unsigned long long big_int;
extern "C" unsigned int strlen(const char *);

#define NULL 0
#define STRINGX_CACHE_BUCKETS 16

class stringx;

class string_buf
{
protected:
    friend class stringx;
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

public:
    inline void inc_ref()
    {
        ref_count++;
    }

    inline int get_ref()
    {
        return ref_count;
    }

    inline int compare(const char *str) const
    {
        int i;
        const char *a = reinterpret_cast<const char *>(data);
        for (i = 0; i < char_length; i++) {
            if (str[i] == '\0') return -1;
            if (a[i] == str[i]) continue;
            if (str[i] > a[i]) return 1;
            if (str[i] < a[i]) return -1;
        }
        if (str[i] == '\0') return 0;
        return 1;
    }

    inline bool is_equal(const char *str) const
    {
        return (compare(str) == 0);
    }
};

class stringx
{
protected:
    static string_buf *buf_cache[256 * STRINGX_CACHE_BUCKETS];
    static string_buf *find_cached_string(const char *str, int len = -1);
};

string_buf *stringx::find_cached_string(const char *str, int len)
{
    if (str == NULL) {
        return NULL;
    }

    if (len == -1)
        len = strlen(str);

    unsigned int start = ((unsigned char) str[0]) * STRINGX_CACHE_BUCKETS;

    for (unsigned int i = start; i < start + STRINGX_CACHE_BUCKETS; i++) {
        if (buf_cache[i] != NULL) {
            if (buf_cache[i]->get_ref() > 0 && buf_cache[i]->is_equal(str) && buf_cache[i]->char_length == len) {
                buf_cache[i]->inc_ref();
                return buf_cache[i];
            }
        }
    }

    return NULL;
}
